// Pedidos do site da deciban (POST /api/proposal e /api/booking → este webhook).
// Normaliza os dois formatos num lead só, com os rótulos legíveis no lugar
// dos ids. O Paroli lê os nós "Entrada" e "Formatar resposta" no sync.
const b = $json.body ?? $json;
const s = (v, max = 400) => (typeof v === 'string' ? v.trim().slice(0, max) : '');

const NEEDS = { agente: 'Agente de IA', crm: 'Automação de CRM / vendas', plataforma: 'Sistema web / SaaS', processos: 'Automação de processos', dados: 'Dados, busca ou painel', outro: 'Outra coisa' };
const BUDGET = { 'ate-3k': 'Até R$ 3 mil', '3-10k': 'R$ 3–10 mil', '10-30k': 'R$ 10–30 mil', '30k+': 'Acima de R$ 30 mil', mensal: 'Prefere mensalidade', 'nao-sei': 'Ainda não sabe' };
const DEADLINE = { urgente: 'Em até 30 dias', '1-3m': '1 a 3 meses', data: 'Tem uma data', 'sem-pressa': 'Sem pressa' };
const DECIDER = { eu: 'Só a pessoa', socios: 'A pessoa e sócio(s)', outro: 'Outra pessoa' };

const meeting = b.event === 'meeting_requested';
const kind = meeting ? 'reuniao' : 'proposta';
const sessionId = `${kind}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;

// horário de Brasília (UTC−3, sem horário de verão) → ISO com fuso
const meetingAt = meeting && /^\d{4}-\d{2}-\d{2}$/.test(b.date) && /^\d{2}:\d{2}$/.test(b.time) ? `${b.date}T${b.time}:00-03:00` : '';

return [{
  json: {
    sessionId,
    mode: meeting ? 'meeting' : 'form',
    locale: b.locale === 'en' ? 'en' : 'pt',
    kind,
    name: s(b.name), role: s(b.role), company: s(b.company), niche: s(b.segment),
    email: s(b.email), whatsapp: s(b.whatsapp, 50),
    needs: Array.isArray(b.needs) ? b.needs.map((n) => NEEDS[n] ?? n).join(', ') : '',
    pain: s(b.pain, 3000) || s(b.message, 3000),
    tools: s(b.tools, 600),
    budget: BUDGET[b.budget] ?? '',
    deadline: [DEADLINE[b.deadline], s(b.deadlineDate, 200)].filter(Boolean).join(' — '),
    decider: DECIDER[b.decider] ?? '',
    history: s(b.history, 1000),
    topic: s(b.topic, 500),
    meetingAt,
    meetingDuration: meeting ? Number(b.duration) || 30 : null,
    consent: b.consent === true,
    consentTs: s(b.consentTs, 40),
    ts: s(b.ts, 40) || new Date().toISOString(),
  },
}];

// Monta o lead no mesmo formato do agente (o Paroli sincroniza daqui).
const e = $('Entrada').first().json;
const resumo = e.kind === 'reuniao'
  ? `Pediu conversa de ${e.meetingDuration} min em ${e.meetingAt.replace('T', ' ').slice(0, 16)} (Brasília). Assunto: ${e.topic || '—'}`
  : `Quer: ${e.needs || '—'}. Dor: ${e.pain || '—'}. Prazo: ${e.deadline || '—'}. Faixa: ${e.budget || '—'}.`;

return [{
  json: {
    ok: true,
    status: 'finalized',
    lead: {
      kind: e.kind,
      name: e.name, role: e.role, company: e.company, niche: e.niche,
      email: e.email, whatsapp: e.whatsapp,
      needs: e.needs, pain: e.pain, tools: e.tools,
      budget: e.budget, deadline: e.deadline, decider: e.decider, history: e.history,
      topic: e.topic, meetingAt: e.meetingAt, meetingDuration: e.meetingDuration,
      summary: resumo.slice(0, 1000),
      sessionId: e.sessionId, mode: e.mode, locale: e.locale, ts: e.ts,
    },
  },
}];
